<template><div class="page"><el-card><template #header><div class="header"><div><b>个人知识库</b><small>关联学习、开发日志、博客和普通笔记，支持复习与 AI 辅助</small></div><div><el-button @click="aiVisible=true">AI 设置/记录</el-button><el-button type="primary" @click="open()">新建笔记</el-button></div></div></template><div class="filters"><el-input v-model="keyword" clearable placeholder="全文搜索标题、Markdown、标签"/><el-input v-model="topic" clearable placeholder="主题"/><el-checkbox v-model="dueOnly">只看待复习</el-checkbox><el-button @click="load">搜索</el-button></div><div class="grid"><article v-for="x in entries" :key="x.id"><div><el-tag size="small">{{sourceName(x.sourceType)}}</el-tag><small>{{x.topic||'未归主题'}}</small></div><h3>{{x.title}}</h3><p>{{(x.markdownContent||'').slice(0,180)}}</p><small>复习：{{x.reviewAt||'未安排'}} · 间隔 {{x.reviewIntervalDays}} 天</small><div class="actions"><el-button @click="open(x)">编辑</el-button><el-button @click="related(x)">关联/相似</el-button><el-button type="success" plain @click="review(x,true)">记住了</el-button><el-button plain @click="review(x,false)">再复习</el-button><el-button type="primary" plain @click="askAi(x)">AI 标签</el-button></div></article><el-empty v-if="!entries.length" description="还没有知识条目"/></div></el-card>
<el-dialog v-model="visible" :title="editing?'编辑知识':'新建 Markdown 笔记'" width="min(720px,95vw)"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><div class="two"><el-form-item label="主题"><el-input v-model="form.topic"/></el-form-item><el-form-item label="项目"><el-input v-model="form.projectName"/></el-form-item></div><el-form-item label="标签"><el-input v-model="form.tags" placeholder="逗号分隔"/></el-form-item><el-form-item label="Markdown"><el-input v-model="form.markdownContent" type="textarea" :rows="12"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="relatedVisible" title="双向链接与相似记录" width="min(640px,94vw)"><el-select v-model="targetId" filterable placeholder="选择要建立双向链接的条目"><el-option v-for="x in entries.filter(e=>e.id!==editing?.id)" :key="x.id" :label="x.title" :value="x.id"/></el-select><el-button :disabled="!targetId" @click="link">建立链接</el-button><h4>已关联</h4><el-tag v-for="x in links" :key="x.id">{{x.title}}</el-tag><h4>相似推荐</h4><el-tag v-for="x in similar" :key="x.id" type="success">{{x.title}}</el-tag></el-dialog>
<el-drawer v-model="aiVisible" title="AI 辅助（结果必须人工确认）" size="min(680px,96vw)"><el-form label-position="top"><div class="two"><el-form-item label="Provider"><el-select v-model="aiConfig.providerType"><el-option label="DeepSeek" value="DEEPSEEK"/></el-select></el-form-item><el-form-item label="模型"><el-input v-model="aiConfig.modelName"/></el-form-item></div><el-form-item label="Base URL"><el-input v-model="aiConfig.baseUrl"/></el-form-item><el-form-item label="API Key（后端加密保存）"><el-input v-model="aiConfig.apiKey" type="password" show-password/></el-form-item><el-button type="primary" @click="saveConfig">保存配置</el-button></el-form><el-divider>调用记录</el-divider><article v-for="x in aiLogs" :key="x.id" class="ai-log"><el-tag :type="x.status==='FAILED'?'danger':'info'">{{x.status}}</el-tag><small>{{x.scene}} · {{x.modelName||'未调用'}} · {{x.createdAt}}</small><p>{{x.resultContent||x.failureReason}}</p><el-button v-if="x.status==='PENDING_CONFIRMATION'" @click="confirmAi(x)">人工确认采用</el-button></article></el-drawer></div></template>
<script setup lang="ts">import{ElMessage}from'element-plus';import{onMounted,reactive,ref}from'vue';import{aiAssist,confirmAiInvocation,listAiInvocations,saveAiConfig,type AiInvocation}from'@/api/ai';import{createKnowledge,linkKnowledge,listKnowledge,listKnowledgeLinks,reviewKnowledge,similarKnowledge,updateKnowledge,type KnowledgeEntry}from'@/api/knowledge';const entries=ref<KnowledgeEntry[]>([]),keyword=ref(''),topic=ref(''),dueOnly=ref(false),visible=ref(false),relatedVisible=ref(false),aiVisible=ref(false),editing=ref<KnowledgeEntry>(),links=ref<KnowledgeEntry[]>([]),similar=ref<KnowledgeEntry[]>([]),targetId=ref<number>(),aiLogs=ref<AiInvocation[]>([]);const form=reactive({title:'',markdownContent:'',tags:'',projectName:'',topic:'',reviewIntervalDays:1}),aiConfig=reactive({providerType:'DEEPSEEK',baseUrl:'https://api.deepseek.com',modelName:'deepseek-chat',apiKey:'',enabled:true});async function load(){entries.value=(await listKnowledge({keyword:keyword.value||undefined,topic:topic.value||undefined,dueOnly:dueOnly.value})).data;}function open(x?:KnowledgeEntry){editing.value=x;Object.assign(form,x?{title:x.title,markdownContent:x.markdownContent||'',tags:x.tags||'',projectName:x.projectName||'',topic:x.topic||'',reviewIntervalDays:x.reviewIntervalDays}:{title:'',markdownContent:'',tags:'',projectName:'',topic:'',reviewIntervalDays:1});visible.value=true;}async function save(){if(!form.title.trim()){ElMessage.warning('请输入标题');return;}if(editing.value)await updateKnowledge(editing.value.id,form);else await createKnowledge(form);visible.value=false;await load();}async function review(x:KnowledgeEntry,remembered:boolean){await reviewKnowledge(x.id,remembered);await load();}async function related(x:KnowledgeEntry){editing.value=x;[links.value,similar.value]=await Promise.all([listKnowledgeLinks(x.id).then(r=>r.data),similarKnowledge(x.id).then(r=>r.data)]);relatedVisible.value=true;}async function link(){if(editing.value&&targetId.value){await linkKnowledge(editing.value.id,targetId.value);await related(editing.value);}}async function askAi(x:KnowledgeEntry){const result=(await aiAssist({scene:'CONTENT_TAGGING',sourceType:'KNOWLEDGE',sourceId:x.id,input:`${x.title}\n${x.markdownContent||''}`})).data;ElMessage[result.status==='FAILED'?'error':'success'](result.status==='FAILED'?(result.failureReason||'AI 调用失败'):'AI 结果已进入待确认列表');aiLogs.value=(await listAiInvocations()).data;aiVisible.value=true;}async function saveConfig(){await saveAiConfig(aiConfig);aiConfig.apiKey='';ElMessage.success('AI 配置已加密保存');}async function confirmAi(x:AiInvocation){await confirmAiInvocation(x.id);aiLogs.value=(await listAiInvocations()).data;}const sourceName=(x:string)=>({MANUAL:'笔记',LEARNING_RECORD:'学习',DEV_LOG:'开发',BLOG_POST:'博客',QUICK_NOTE:'记录'}[x]||x);onMounted(async()=>{await load();aiLogs.value=(await listAiInvocations()).data;});</script>
<style scoped>.page{display:flex;flex-direction:column;gap:14px}.header,.header>div:last-child,.filters,.actions{display:flex;align-items:center;justify-content:space-between;gap:8px}.header small,article small{display:block;color:#718096}.filters{justify-content:flex-start;margin-bottom:16px}.filters .el-input{max-width:280px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.grid article,.ai-log{padding:16px;border:1px solid #e4eaf2;border-radius:14px}.grid article>div{display:flex;justify-content:space-between}.grid p{min-height:48px;color:#52606d;white-space:pre-wrap}.actions{justify-content:flex-start;flex-wrap:wrap;margin-top:14px}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.ai-log{margin-bottom:10px}.ai-log p{white-space:pre-wrap}@media(max-width:768px){.header,.filters{align-items:stretch;flex-direction:column}.grid{grid-template-columns:1fr}.two{grid-template-columns:1fr}}</style>
